using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.TKT.DocumentosTicket;using GraphApi.Services.TKT.DocumentosTicket;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.TKT.DocumentosTicket{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de DocumentosTickets: creación, actualización y eliminación.")]    public class DocumentosTicketMutation    {        [Authorize]        [GraphQLName("createDocumentosTicket")]        [GraphQLDescription("Crea un nuevo DocumentosTicket usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadDocumentosTicket> CreateDocumentosTicketAsync(            [GraphQLDescription("Datos necesarios para crear el DocumentosTicket.")]            clCreateDocumentosTicket objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de DocumentosTicket.")]            IDocumentosTicketService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateDocumentosTicket(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateDocumentosTicket")]        [GraphQLDescription("Actualiza los campos especificados de un DocumentosTicket existente.")]        public async Task<clReadDocumentosTicket?> UpdateDocumentosTicketAsync(            [GraphQLDescription("Datos del DocumentosTicket a actualizar.")]            clUpdateDocumentosTicket objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de DocumentosTicket.")]            IDocumentosTicketService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateDocumentosTicket(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteDocumentosTicket")]        [GraphQLDescription("Elimina un DocumentosTicket por su ID.")]        public async Task<bool> delDocumentosTicketAsync(            [GraphQLDescription("ID del DocumentosTicket a eliminar.")]            int nDocumentosTicketID,            [Service]            [GraphQLDescription("Servicio para operaciones de DocumentosTicket.")]            IDocumentosTicketService objService        )        {            return await objService.DeleteDocumentosTicket(nDocumentosTicketID);        }    }}